ROOT=Path(r'D:\Github\BI 2026');OUT=ROOT/'Workshop 6 การสร้างโมเดลและการประเมินผล';SUP=OUT/'support';EVIDENCE=OUT/'evidence';EVIDENCE.mkdir(exist_ok=True)
MINI=ROOT/'BI Mini Project 2';NATIVE=ROOT/'Native_AI_Repository/MiniProject2_AutoModel_9Models/Naive Bayes/Performance.rmperf'
native_bytes=NATIVE.read_bytes();native=json.loads(native_bytes);audit=json.loads((MINI/'native_result_audit.json').read_text(encoding='utf-8'));a=audit['models']['Naive Bayes'];assert hashlib.sha256(native_bytes).hexdigest()==a['native_sha256']
criteria={}
for name,(suffix,code) in {'Accuracy':('MultiClassificationPerformance',0),'Precision':('BinaryClassificationPerformance',0),'Recall':('BinaryClassificationPerformance',1),'F1':('BinaryClassificationPerformance',4),'AUC':('AreaUnderCurve$Neutral',None)}.items():
    c=next(c for c in native['averagesList'] if c['rm_object_type'].endswith(suffix) and (code is None or c['type']==code));assert c['averageCount']==5
    mean=c['meanSum']/5;sd=math.sqrt(max(0,(c['meanSquaredSum']-c['meanSum']**2/5)/4));assert math.isclose(mean,a['metrics'][name]['mean'],abs_tol=1e-14)
    criteria[name]={'mean':mean,'sample_sd':sd,'GUI_percent':round(mean*100,1),'average_count':5,'meanSum':c['meanSum'],'meanSquaredSum':c['meanSquaredSum']}
matrix=next(c for c in native['averagesList'] if c['rm_object_type'].endswith('MultiClassificationPerformance') and c['type']==0)
assert matrix['classNames']==['Outpatient','Hospitalized'];tn,fp=map(int,matrix['counter'][0]);fn,tp=map(int,matrix['counter'][1]);n=tn+fp+fn+tp
assert (tn,fp,fn,tp,n)==(228013,14416,21684,35480,299593)
pooled={'Accuracy':(tp+tn)/n,'Precision':tp/(tp+fp),'Recall':tp/(tp+fn),'F1':2*tp/(2*tp+fp+fn)}
negative={'Precision':tn/(tn+fn),'Recall':tn/(tn+fp),'F1':2*tn/(2*tn+fn+fp)}
macro={name:(pooled[name]+negative[name])/2 for name in ['Precision','Recall','F1']};micro={name:pooled['Accuracy']for name in ['Precision','Recall','F1']}
auc=next(c for c in native['averagesList'] if c['rm_object_type'].endswith('AreaUnderCurve$Neutral'));assert auc['positiveClass']=='Hospitalized' and auc['method']=='NEUTRAL'
assert all(c['positiveClassName']=='Hospitalized' and c['negativeClassName']=='Outpatient' for c in native['averagesList'] if c['rm_object_type'].endswith('BinaryClassificationPerformance'))
curve_areas=[]
for curve in auc['rocData']:
    points=curve['points'];assert points[0]['falsePositives']==0 and points[0]['truePositives']==0
    assert points[-1]['falsePositives']==curve['sumNeg'] and points[-1]['truePositives']==curve['sumPos']
    area=sum((q['falsePositives']-p['falsePositives'])*(q['truePositives']+p['truePositives'])/(2*curve['sumNeg']*curve['sumPos']) for p,q in zip(points,points[1:]))
    curve_areas.append(area)
assert len(curve_areas)==5 and math.isclose(sum(curve_areas)/5,criteria['AUC']['mean'],abs_tol=1e-12)
assert sum(c['sumPos'] for c in auc['rocData'])==tp+fn and sum(c['sumNeg'] for c in auc['rocData'])==tn+fp
original_shot=MINI/'screenshots/native_NB_performance.png';shot=EVIDENCE/'native_NB_performance.png';shutil.copy2(original_shot,shot);assert hashlib.sha256(shot.read_bytes()).digest()==hashlib.sha256(original_shot.read_bytes()).digest()
snapshot={'source_native_file':str(NATIVE),'source_native_sha256':hashlib.sha256(native_bytes).hexdigest(),'source_screenshot':str(original_shot),'copied_screenshot_sha256':hashlib.sha256(shot.read_bytes()).hexdigest(),'positive_class':'Hospitalized','negative_class':'Outpatient','native_robust_batch_means':criteria,'confusion':{'TN':tn,'FP':fp,'FN':fn,'TP':tp,'N':n},'pooled_positive_class':pooled,'class_negative':negative,'class_macro':macro,'micro_all_classes':micro,'native_retained_ROC_areas':curve_areas,'native_ROC_mean_reproduced':True,'majority_baseline_accuracy':(tn+fp)/n,'mean_F1_not_F1_of_mean_PR':{'native_mean_F1':criteria['F1']['mean'],'F1_of_native_mean_P_R':2*criteria['Precision']['mean']*criteria['Recall']['mean']/(criteria['Precision']['mean']+criteria['Recall']['mean'])},'new_native_run_performed':False,'shared_test_comparison_complete':False,'checked_at':datetime.datetime.now().isoformat()}
