def p(t,style=B):return Paragraph(escape(t).replace('\n','<br/>'),style)
def pct(x,d=4):return f'{100*x:.{d}f}%'
def tab(rows,widths):
    t=Table([[p(str(c),S)for c in row]for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E4EDF4')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F5F7F9')]),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#17324D'))]));return t
def heading(t):return p(t,H)
def footer(c,doc):
    c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#607180'));c.drawString(42,25,'Workshop 6 | Authentic NB checkpoint + transparent metric calculations');c.drawRightString(553,25,str(doc.page))
def roc_drawing():
    d=Drawing(510,330);x0=45;y0=45;w=430;h=240;palette=['#227C9D','#1E847F','#836CB2','#BE8742','#719C36']
    for i in range(6):
        value=i/5;x=x0+value*w;y=y0+value*h;d.add(Line(x,y0,x,y0+h,strokeColor=colors.HexColor('#E5EAF0')));d.add(Line(x0,y,x0+w,y,strokeColor=colors.HexColor('#E5EAF0')));d.add(String(x-7,y0-15,f'{value:.1f}',fontSize=8));d.add(String(x0-24,y-3,f'{value:.1f}',fontSize=8))
    d.add(Line(x0,y0,x0+w,y0+h,strokeColor=colors.HexColor('#A6ADB5'),strokeDashArray=[3,3]))
    for i,curve in enumerate(auc['rocData']):
        points=curve['points'];stride=max(1,len(points)//600);sample=points[::stride]+[points[-1]];xy=[]
        for q in sample:xy.extend([x0+w*q['falsePositives']/curve['sumNeg'],y0+h*q['truePositives']/curve['sumPos']])
        d.add(PolyLine(xy,strokeColor=colors.HexColor(palette[i]),strokeWidth=1.2));d.add(String(58+(i%3)*142,312-(i//3)*13,f'Retained {i+1}: AUC {curve_areas[i]:.4f}',fontSize=8,fillColor=colors.HexColor(palette[i])))
    d.add(String(200,8,'False Positive Rate (FPR)',fontSize=9));d.add(String(1,292,'TPR',fontSize=9));return d

story=[heading('Workshop 6 - เกณฑ์ประเมินโมเดล 5 ข้อ'),p('ตัวอย่างจริง: Naive Bayes จำแนก PATIENT_TYPE จาก COVID Data ใน Mini Project2. Positive class = Hospitalized (รหัส2); Negative class = Outpatient (รหัส1). Positive ในงานนี้หมายถึงประเภทผู้ป่วยที่รับไว้รักษา ไม่ใช่ผลตรวจเชื้อหรือการเสียชีวิต.'),p('โจทย์1.txt ระบุ Precision, Recall, Accuracy, F-Measure และ AUC. รายงานใช้ภาพ native_NB_performance.png และ checkpoint ที่บันทึกจาก Auto Model จริง ไม่สร้างผลการ Run ใหม่. ภาพ GUI แสดง Altair AI Studio Educational2026.1.1; serialized checkpoint มี object version12.1.1.'),tab([['เกณฑ์','Native mean ±SD (percentage points)','GUI'],*[[m,pct(criteria[m]['mean'],6)+' ± '+f"{criteria[m]['sample_sd']*100:.6f}",f"{criteria[m]['GUI_percent']:.1f}%"] for m in ['Precision','Recall','Accuracy','F1','AUC']]],[95,305,110]),Spacer(1,12),p('ตัวเลขด้านบนเป็นค่าเฉลี่ยแบบ robust ของ5holdout batches ที่คงไว้จาก7batches. เป็นการเฉลี่ยตาม batches ไม่ใช่ class macro average และไม่ใช่ five-fold cross-validation. จะเทียบกับค่า pooled จาก confusion counts และ class macro แยกในรายงาน.'),p('แหล่งบทเรียน: BI06 เป็นพื้นฐาน Data Preparation/Turbo Prep; รายการเกณฑ์และตัวอย่าง Evaluation/Confusion Matrix/F1 อยู่ใน BI08. ใช้ตัวอย่าง COVID เป็นบริบทและใช้ผล Naive Bayes จริงของงานนี้เป็นตัวเลข.'),PageBreak()]

story += [heading('Confusion Matrix และความหมายของ counts'),p('รายงานจัดแถวเป็นค่าจริง และคอลัมน์เป็นค่าพยากรณ์ เพื่ออ่านสูตรได้ตรงกัน. ภาพ GUI เดิมแสดงแถวเป็นค่าพยากรณ์และคอลัมน์เป็นค่าจริง ซึ่งเป็นการ transpose ตาราง ไม่ใช่ counts ต่างชุด.'),tab([['Actual /Prediction','Outpatient (-)','Hospitalized (+)','รวมจริง'],['Outpatient (-)',f'TN={tn:,}',f'FP={fp:,}',f'{tn+fp:,}'],['Hospitalized (+)',f'FN={fn:,}',f'TP={tp:,}',f'{tp+fn:,}'],['รวมพยากรณ์',f'{tn+fn:,}',f'{tp+fp:,}',f'N={n:,}']],[155,120,120,115]),Spacer(1,12),p('TP: พยากรณ์ Hospitalized และเป็น Hospitalized จริง. FP: พยากรณ์ Hospitalized แต่จริงเป็น Outpatient. FN: พยากรณ์ Outpatient แต่จริงเป็น Hospitalized. TN: พยากรณ์ Outpatient และเป็น Outpatient จริง.'),p(f'Counts รวมที่ถูกเก็บใน checkpoint เท่ากับ{n:,}ระเบียน; ROC ของ5batchesรวม positives={tp+fn:,}และ negatives={tn+fp:,}ตรงกัน. จำนวนนี้ไม่ใช่จำนวนผู้ป่วยไม่ซ้ำ และไม่ใช่หลักฐานว่าโมเดลทั้ง9ใช้ Testing Set ร่วมกัน.'),tab([['ค่าจาก countsรวม','การแทนค่า','ผล'],['Precision',f'{tp:,}/({tp:,}+{fp:,})',pct(pooled['Precision'],6)],['Recall',f'{tp:,}/({tp:,}+{fn:,})',pct(pooled['Recall'],6)],['Accuracy',f'({tp:,}+{tn:,})/{n:,}',pct(pooled['Accuracy'],6)],['F1',f'2×{tp:,}/(2×{tp:,}+{fp:,}+{fn:,})',pct(pooled['F1'],6)]],[105,275,130]),PageBreak()]

story += [heading('1. Precision และ2. Recall'),p('Precision = TP/(TP+FP). ถามว่า ในระเบียนที่โมเดลพยากรณ์เป็น Positive มีส่วนที่เป็น Positive จริงเท่าไร. ตัวหารเป็นจำนวนพยากรณ์ Positive ไม่ใช่จำนวน Positive จริง.'),p(f'ตัวอย่าง pooled: ใน{tp+fp:,}ระเบียนที่พยากรณ์ Hospitalized มี{tp:,}ระเบียนเป็น Hospitalized จริง จึงได้ Precision={pct(pooled["Precision"],6)}. Native batch mean={pct(criteria["Precision"]["mean"],6)} และ GUIปัดเป็น71.1%.'),p('Recall = TP/(TP+FN), เรียก Sensitivity หรือ True Positive Rate. ถามว่า ใน Positive จริงทั้งหมด โมเดลค้นพบถูกต้องเท่าไร. ตัวหารเป็นจำนวน Positive จริง.'),p(f'ตัวอย่าง pooled: Hospitalizedจริง{tp+fn:,}ระเบียน ค้นพบถูก{tp:,}ระเบียน จึงได้ Recall={pct(pooled["Recall"],6)}. ยังมี FN={fn:,}ระเบียน หรือ{pct(fn/(tp+fn),4)}ของPositiveจริงที่พยากรณ์เป็นOutpatient. Native mean={pct(criteria["Recall"]["mean"],6)} และ GUI62.1%.'),tab([['ประเด็น','Precision','Recall'],['ตัวหาร','TP+FP: พยากรณ์Positive','TP+FN: Positiveจริง'],['ความผิดพลาดที่กดค่า','FP มากทำให้ลด','FN มากทำให้ลด'],['อ่านกรณีนี้','ประมาณ71%ของPositiveที่ทายเป็นจริง','พบประมาณ62%ของPositiveจริง']],[130,190,190]),Spacer(1,12),p('เลือกเกณฑ์ให้สัมพันธ์กับต้นทุนความผิดพลาดตามโจทย์: ต้องตรวจ FP เมื่อสนใจความน่าเชื่อถือของผล Positive และต้องตรวจ FN เมื่อสนใจ Positive ที่พลาด. ตัวเลขไม่บอกเหตุผลเชิงสาเหตุหรือความเหมาะสมในการใช้งานใหม่โดยตัวมันเอง.'),PageBreak()]

story += [heading('3. Accuracy และ4. F-Measure /F1'),p('Accuracy = (TP+TN)/(TP+TN+FP+FN). เป็นสัดส่วนพยากรณ์ถูกทั้งหมด รวมทั้งสองคลาส.'),p(f'ตัวอย่าง pooled: ({tp:,}+{tn:,})/{n:,} = {pct(pooled["Accuracy"],6)}. Native robust mean={pct(criteria["Accuracy"]["mean"],6)}, GUI88.0%. ในcountsชุดนี้ หากพยากรณ์ทุกระเบียนเป็นOutpatientจะได้ baseline={(tn+fp):,}/{n:,}={pct((tn+fp)/n,4)} จึงไม่ควรใช้ Accuracy เพียงค่าเดียวกับคลาสที่ไม่สมดุล.'),p('F1 = 2×Precision×Recall/(Precision+Recall) = 2TP/(2TP+FP+FN). เป็น harmonic mean ที่รวม Precision และRecall; ไม่ใช่ (Precision+Recall)/2.'),p(f'ตัวอย่าง pooled: {2*tp:,}/{2*tp+fp+fn:,} = {pct(pooled["F1"],6)}. Native mean F1={pct(criteria["F1"]["mean"],6)}, GUI66.3%.'),p(f'F1จากP/Rที่เฉลี่ยแล้ว = {pct(snapshot["mean_F1_not_F1_of_mean_PR"]["F1_of_native_mean_P_R"],6)} ซึ่งต่างจากค่าเฉลี่ยF1จริง. ต้องคำนวณF1ของแต่ละbatchก่อนเฉลี่ย เพราะสูตรเป็น nonlinear; ไม่แทนค่า meanP/meanRแล้วเรียกว่าค่าnativeเดียวกัน.'),p('SD ที่ GUI Accuracy แสดง ±0.0% ไม่ได้แปลว่า SDเป็นศูนย์: checkpoint มี SD='+f"{criteria['Accuracy']['sample_sd']*100:.6f}"+'percentage points ก่อนปัด. SDสะท้อนความแตกต่างใน5batches ไม่ใช่ confidence interval ของ Accuracy.'),PageBreak()]

story += [heading('5. Area Under Curve (AUC-ROC)'),p('ROC วางแกนY = TPR = TP/(TP+FN) และแกนX = FPR = FP/(FP+TN). เปลี่ยน threshold แล้วได้หลายจุด; AUC คือพื้นที่ใต้เส้น ROC. ไม่ใช่ Accuracy และหาไม่ได้จาก confusion matrix ของ threshold เดียว.'),p('สูตรพื้นที่แบบ trapezoid: AUC = Σ (FPR[i]-FPR[i-1])×(TPR[i]+TPR[i-1])/2. AUCวัดการจัดอันดับคะแนนPositiveเทียบNegative. สำหรับคะแนนเสมอกัน Altair AUCแบบneutralใช้ค่าเฉลี่ยของ optimistic และpessimistic.'),roc_drawing(),p('รูปด้านบนวาดใหม่จากจุด ROC จริงใน native checkpoint ทั้ง5ชุด ไม่ใช่ภาพหน้าจอ GUIหรือเส้นสมมติ. ชื่อRetained1-5ใช้แสดงลำดับที่เก็บ ไม่ใช่หมายเลขfold. คำนวณพื้นที่จากทุกจุดก่อนลดจำนวนจุดเพื่อวาดรูป.',S),tab([['ROC retained batch','AUCคำนวณจากจุดจริง','Positive /Negative'],*[[i+1,f'{area:.9f}',f"{int(curve['sumPos']):,} / {int(curve['sumNeg']):,}"]for i,(area,curve)in enumerate(zip(curve_areas,auc['rocData']))],['mean',f"{sum(curve_areas)/5:.9f}",'averageCount=5']],[130,200,180]),p(f'ค่าเฉลี่ยพื้นที่ตรงกับnative AUC={criteria["AUC"]["mean"]:.9f}; GUIแสดง88.2%. ค่า0.5เป็นระดับการจัดอันดับสุ่มในความหมายROC; ค่า0.881848ไม่ได้หมายถึงทายถูก88.1848%ของระเบียน.'),PageBreak()]

story += [heading('การเฉลี่ย3แบบที่ต้องแยกให้ชัด'),p('1) Native robust batch mean: คำนวณ metricแต่ละbatchแล้วให้น้ำหนักเท่ากันใน5ชุดที่คงไว้. mean=meanSum/averageCount; SD=sqrt((meanSquaredSum-meanSum²/k)/(k-1)), k=5. ค่า GUI Performance ใช้วิธีนี้.'),p('2) Pooled positive-class metric: รวม TP/FP/FN/TNที่เก็บ แล้วค่อยคำนวณสูตรของHospitalized. ตัวหารและการให้น้ำหนักต่างจากmeanของอัตราส่วน จึงต่างเล็กน้อยได้โดยไม่ใช่ข้อผิดพลาด.'),p('3) Class macro: คำนวณ Precision/Recall/F1ของHospitalizedและOutpatientแยกกันแล้วเฉลี่ยสองคลาสเท่ากัน. Macro F1=(F1Hospitalized+F1Outpatient)/2 ไม่ใช่ F1จากmacroP/R. ค่าเหล่านี้ด้านล่างคำนวณเพิ่มจากcountsจริง แต่ไม่ได้อ้างว่าเป็นค่าใน GUI.'),tab([['Metric','Native batch mean','PooledHospitalized','Class macro'],*[[m,pct(criteria[m]['mean'],6),pct(pooled[m],6),pct(macro[m],6)]for m in ['Precision','Recall','F1']],['Accuracy',pct(criteria['Accuracy']['mean'],6),pct(pooled['Accuracy'],6),'ไม่ใช้class-macroaccuracy'],['AUC',f"{criteria['AUC']['mean']:.9f}",'CMเดียวคำนวณไม่ได้','ไม่ได้คำนวณclassmacroAUC']],[80,145,145,140]),Spacer(1,10),p('เพิ่มเติม: micro averagingข้ามทั้งสองคลาสรวม TP/FP/FNของทุกคลาสก่อนคำนวณ. สำหรับ single-label classificationนี้ microPrecision=microRecall=microF1=Accuracy='+pct(pooled['Accuracy'],6)+'. ไม่ใช่ pooledHospitalizedPrecision71.1079%. การเรียกทุกแบบว่าmacroหรือmicroโดยไม่ระบุขอบเขตจึงทำให้สรุปผิด.'),p('ตัวอย่างนี้ไม่ใช้ผลdefault9โมเดลเพื่อเลือกผู้ชนะบนTestingSetร่วมกัน: native auditยืนยันว่ามี initial sample capsและจำนวนconfusion recordsไม่เท่ากัน. งานcommon-holdoutของMini2ยังเป็นอีกขั้นตอนหนึ่ง; รายงานWS6นี้ไม่ได้ประกาศว่างานนั้นเสร็จแล้ว.'),PageBreak()]

